/* 仿qq·黑 by点星 禁止二传 */
:root {
  --chat-header-bg: #2c2c2e; /* 淡黑深灰顶栏底色 */
  --input-area-bg: #2c2c2e; /* 底栏同步淡黑色 */
  --chat-header-title-color: #d4af37; /* 备注标题金色不变 */
}

/* 彻底隐藏顶栏原生头像 */
.header-avatar-container,
.chat-header-avatar {
  display: none !important;
  visibility: hidden !important;
}

/* 左一返回图标强制白色 */
.header-btn-back {
  filter: brightness(0) invert(1) !important;
}

/* 右一设置键 图标白色+尺寸 */
.header-btn-info {
  background: url(https://imgbed.heliar.top/file/1781164798881_retouch_2026061115593993.png) center / 16px no-repeat !important;
  width: 24px !important;
  height: 24px !important;
  filter: brightness(0) invert(1) !important;
}
.header-btn-info svg {
  display: none !important;
}

/* 【核心修复】右二、右三：仅隐藏内部原生图标，强制保留外层按钮点击权限，提升层级避免拦截 */
 .header-btn-phone,
 .header-btn-video {
   pointer-events: auto !important;
   position: relative !important;
   z-index: 10 !important;
   width: 32px !important;
   height: 32px !important;
 }
 .header-btn-phone svg,
 .header-btn-video svg {
   display: none !important;
   visibility: hidden !important;
 }

/* 顶栏整体排布 */
.chat-header-custom {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  position: relative !important;
}

/* 主标题，保持inline-flex自适应跟随结构不变 */
.chat-header-title {
  margin-left: -10px !important; /* 负数越小，越往左 */
  position: relative !important;
  top: -7px !important; /* 备注+图标整体上移，负数越小，越往上 */
  line-height: 1.2 !important;
  display: inline-flex !important;
  align-items: center !important;
}

/* 备注文字后面跟随图标，长短自动适配 完全保留 */
.chat-header-title::after {
  content: "";
  display: inline-block !important;
  width: 49px;
  height: 49px;
  margin-left: 7px; /* 数字越大，备注标题和图标间距越大 */
  background: url(https://imgbed.heliar.top/file/1781164105348_retouch_2026061114525961.png) center/contain no-repeat;
  pointer-events: none;
}

