 */

/* --- 1. 整体布局 & 弱化顶线 --- */
.input-area-custom {
  position: relative; 
  padding: 8px 12px 45px 12px !important; 
  display: block;
  min-height: auto;
  border-top: none !important; /* 彻底移除上边框 */
  box-shadow: none !important;
  backdrop-filter: blur(6px) !important;
  -webkit-backdrop-filter: blur(6px) !important;
  overflow: hidden; 
}

/* --- 2. 外层输入框容器 淡黑色底色，输入框改为白灰色 */
.input-action-bar-custom {
  position: relative; 
  z-index: 1;
  display: flex;    
  align-items: center;
  width: 100% !important;
  background: #38383a !important;
  padding: 2px 10px !important;
  border-radius: 24px !important;
  border: 1px solid rgba(255,255,255,0.15) !important;
}

/* --- 3. 核心输入框 textarea 白灰底色+白色文字 */
.input-box-custom {
  flex-grow: 1;
  background: #e2e2e4 !important;
  min-height: 0 !important;
  padding: 2px 4px !important;
  line-height: 16px !important;
  max-height: 24px !important;
  color: #ffffff !important;

  /* 隐藏滚动条 全平台兼容 */
  overflow: hidden !important;
  &::-webkit-scrollbar {
    display: none !important;
    width: 0 !important;
    height: 0 !important;
  }
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}

/* 隐藏占位提示文字 */
.input-box-custom::placeholder {
  color: transparent !important;
  opacity: 0 !important;
}

/* 隐藏原生按钮容器 */
.input-action-bar-custom .input-btns-right {
  display: none;
}

/* --- 4. 底部五个按钮 (可独立调节 left / top) --- */
.input-btn-plus,
.input-btn-mic,
.input-btn-sticker,
.input-btn-ai,
.send-btn-custom,
.stop-btn-custom {
  position: absolute !important; 
  order: initial;
  z-index: 1;

  /* 基础样式，确保按钮正确显示 */
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  line-height: 1 !important;

  /* 默认使用 transform 居中，如需微调可以覆盖 */
  transform: translateX(-50%);

  /* ===== 新增：隐藏原生图标，但保留按钮可点击 ===== */
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}

/* 隐藏按钮内部的所有图标/图片/文字内容 */
.input-btn-plus img,
.input-btn-plus svg,
.input-btn-plus i,
.input-btn-plus span,
.input-btn-mic img,
.input-btn-mic svg,
.input-btn-mic i,
.input-btn-mic span,
.input-btn-sticker img,
.input-btn-sticker svg,
.input-btn-sticker i,
.input-btn-sticker span,
.input-btn-ai img,
.input-btn-ai svg,
.input-btn-ai i,
.input-btn-ai span,
.send-btn-custom img,
.send-btn-custom svg,
.send-btn-custom i,
.send-btn-custom span,
.stop-btn-custom img,
.stop-btn-custom svg,
.stop-btn-custom i,
.stop-btn-custom span {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
